# Generated by test-lab — blind adversarial evaluation
"""Tests for AReW directional critique advantage shaping.

Validates the directional_critique_advantage() function from train_grpo.py
per arXiv 2603.12109 requirements:
  - Binary critique: +1 (informative), -1 (uninformative), 0 (neutral)
  - Zero-sum reallocation within batch
  - Malformed JSON → -1
  - Hallucinated skills → -1
  - Exact match → +1
  - Partial match → 0
"""

import json
import sys
from pathlib import Path

import pytest

# Add scripts dir to path so we can import train_grpo
sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "scripts"))
from train_grpo import directional_critique_advantage


KNOWN_SKILLS = {"memory", "plan", "assess", "taxonomy", "dogpile", "embedding", "assistant"}


class TestAReWBasicCritique:
    """Test binary critique assignment (+1, -1, 0).

    Single-element batches always produce adj=0 due to zero-sum.
    So we test critique direction by pairing against a known-bad baseline.
    """

    def test_exact_match_beats_malformed(self):
        """Exact match gets higher adjustment than malformed JSON."""
        completions = [
            json.dumps({"skills": ["memory", "plan"], "rationale_prompt": "test"}),
            "not json at all",
        ]
        gt = [["memory", "plan"], ["memory"]]
        adj = directional_critique_advantage(completions, gt, KNOWN_SKILLS)
        assert adj[0] > adj[1]

    def test_malformed_json_gets_negative_in_batch(self):
        """Malformed JSON gets negative adjustment when paired with good completion."""
        completions = [
            json.dumps({"skills": ["memory"]}),
            "not json at all",
        ]
        gt = [["memory"], ["memory"]]
        adj = directional_critique_advantage(completions, gt, KNOWN_SKILLS)
        assert adj[1] < 0

    def test_hallucinated_skill_penalized(self):
        """Hallucinated skill gets lower adjustment than valid skill."""
        completions = [
            json.dumps({"skills": ["memory"]}),
            json.dumps({"skills": ["memory", "nonexistent-skill"]}),
        ]
        gt = [["memory"], ["memory"]]
        adj = directional_critique_advantage(completions, gt, KNOWN_SKILLS)
        assert adj[0] > adj[1]

    def test_empty_skills_penalized(self):
        """Empty skills list gets lower adjustment than valid prediction."""
        completions = [
            json.dumps({"skills": ["memory"]}),
            json.dumps({"skills": []}),
        ]
        gt = [["memory"], ["memory"]]
        adj = directional_critique_advantage(completions, gt, KNOWN_SKILLS)
        assert adj[0] > adj[1]

    def test_no_skills_key_penalized(self):
        """Missing skills key gets lower adjustment than valid output."""
        completions = [
            json.dumps({"skills": ["memory"]}),
            json.dumps({"rationale": "test"}),
        ]
        gt = [["memory"], ["memory"]]
        adj = directional_critique_advantage(completions, gt, KNOWN_SKILLS)
        assert adj[0] > adj[1]

    def test_single_element_is_zero(self):
        """Single-element batch always produces 0 adjustment (zero-sum)."""
        completions = [json.dumps({"skills": ["memory"]})]
        gt = [["memory"]]
        adj = directional_critique_advantage(completions, gt, KNOWN_SKILLS)
        assert abs(adj[0]) < 1e-6

    def test_partial_match_between_good_and_bad(self):
        """Partial overlap (jaccard < 0.5) is neutral, between exact and malformed."""
        completions = [
            json.dumps({"skills": ["memory", "plan"]}),       # exact → +1
            json.dumps({"skills": ["memory", "assess"]}),     # partial → 0
            "garbage",                                          # bad → -1
        ]
        gt = [
            ["memory", "plan"],
            ["memory", "plan", "taxonomy", "dogpile"],
            ["assess"],
        ]
        adj = directional_critique_advantage(completions, gt, KNOWN_SKILLS)
        assert adj[0] > adj[1]  # exact > partial
        assert adj[1] > adj[2]  # partial > malformed


class TestAReWZeroSum:
    """Test zero-sum reallocation property."""

    def test_adjustments_sum_to_zero(self):
        completions = [
            json.dumps({"skills": ["memory", "plan"]}),         # exact match → +1
            "bad json",                                          # malformed → -1
            json.dumps({"skills": ["memory"]}),                  # partial → 0 or +1
        ]
        gt = [
            ["memory", "plan"],
            ["assess"],
            ["memory", "plan"],
        ]
        adj = directional_critique_advantage(completions, gt, KNOWN_SKILLS)
        assert len(adj) == 3
        assert abs(sum(adj)) < 1e-6, f"Adjustments must sum to zero, got {sum(adj)}"

    def test_all_same_critique_zero_adjustment(self):
        """If all completions get same critique, adjustments should all be ~0."""
        completions = [
            json.dumps({"skills": ["memory", "plan"]}),
            json.dumps({"skills": ["memory", "plan"]}),
        ]
        gt = [["memory", "plan"], ["memory", "plan"]]
        adj = directional_critique_advantage(completions, gt, KNOWN_SKILLS)
        for a in adj:
            assert abs(a) < 1e-6

    def test_mixed_batch_redistributes(self):
        """Good completion should get positive, bad should get negative."""
        completions = [
            json.dumps({"skills": ["memory", "plan"]}),  # good
            "garbage",                                      # bad
        ]
        gt = [["memory", "plan"], ["assess"]]
        adj = directional_critique_advantage(completions, gt, KNOWN_SKILLS)
        assert adj[0] > 0, "Good completion should get positive adjustment"
        assert adj[1] < 0, "Bad completion should get negative adjustment"
        assert abs(sum(adj)) < 1e-6


class TestAReWEdgeCases:
    """Edge cases and robustness."""

    def test_empty_input(self):
        adj = directional_critique_advantage([], [], KNOWN_SKILLS)
        assert adj == []

    def test_no_known_skills_skips_hallucination_check(self):
        completions = [json.dumps({"skills": ["anything-goes", "made-up"]})]
        gt = [["anything-goes", "made-up"]]
        adj = directional_critique_advantage(completions, gt, known_skills=None)
        # Should not penalize since no known_skills set
        assert isinstance(adj[0], float)

    def test_alpha_scaling(self):
        completions = [
            json.dumps({"skills": ["memory"]}),
            "bad",
        ]
        gt = [["memory"], ["plan"]]

        adj_low = directional_critique_advantage(completions, gt, KNOWN_SKILLS, alpha=0.1)
        adj_high = directional_critique_advantage(completions, gt, KNOWN_SKILLS, alpha=1.0)

        # Higher alpha → larger magnitude adjustments
        assert abs(adj_high[0]) > abs(adj_low[0])

    def test_accepts_trajectory_returns_modified_advantages(self):
        """Core DoD assertion: function accepts trajectory, returns modified advantages."""
        completions = [
            json.dumps({"skills": ["memory", "plan"], "rationale_prompt": "chain"}),
            json.dumps({"skills": ["assess"], "rationale_prompt": "single"}),
            "invalid json",
        ]
        gt = [
            ["memory", "plan"],
            ["assess", "taxonomy"],
            ["dogpile"],
        ]
        adj = directional_critique_advantage(completions, gt, KNOWN_SKILLS)

        # Returns list of floats
        assert isinstance(adj, list)
        assert len(adj) == len(completions)
        assert all(isinstance(a, float) for a in adj)

        # Zero-sum
        assert abs(sum(adj)) < 1e-6
